window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-15c200c54b86e1c5"]={"versions": [{"id": "FIG-15c200c54b86e1c5", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentyp-Definition im Kontext des AUTOSAR-Systemtemplates (Topologie und Signalpfad-Constraints). Das Diagramm spezifiziert die Richtungsaufzählung für Argumente bei Software-Component-zu-Software-Component-Operationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Enumeration:</p>\n<ul class=\"fig-list\"><li><code>SwcToSwcOperationArgumentsDirectionEnum</code> («enumeration») mit den beiden Literalen:\n<ul class=\"fig-list\"><li><code>in</code>\n</li><li><code>out</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Die Literale definieren diskrete Richtungsangaben für die Argumentübergabe bei Funktions- und Methodenaufrufen über Komponentengrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Bestandteil des AUTOSAR-M1-Metamodells. Bei der Spezifikation von Operationen und deren Signalen im System-Template legt dieses Enum fest, ob ein Operationsargument als Eingangs- oder Ausgangsdatenstrom über einen Signalpfad zu routen ist.</p>"}, {"id": "FIG-aa46f7fbe8833451", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentyp-Definition im Kontext des AUTOSAR-Systemtemplates (Topologie und Signalpfad-Constraints). Das Diagramm spezifiziert die Richtungsaufzählung für Argumente bei Software-Component-zu-Software-Component-Operationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Enumeration:</p>\n<ul class=\"fig-list\"><li><code>SwcToSwcOperationArgumentsDirectionEnum</code> («enumeration») mit den beiden Literalen:\n<ul class=\"fig-list\"><li><code>in</code>\n</li><li><code>out</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Die Literale definieren diskrete Richtungsangaben für die Argumentübergabe bei Funktions- und Methodenaufrufen über Komponentengrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Bestandteil des AUTOSAR-M1-Metamodells. Bei der Spezifikation von Operationen und deren Signalen im System-Template legt dieses Enum fest, ob ein Operationsargument als Eingangs- oder Ausgangsdatenstrom über einen Signalpfad zu routen ist.</p>"}, {"id": "FIG-ee1ce48cd516e6d3", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Metamodell-Klassendiagramm für Topologie- und Signalpfad-Constraints im AUTOSAR System Template. Es beschreibt die Struktur von <code>CommonSignalPath</code> zur Erzwingung identischer Übertragungswege für Signale bzw. Operationsargumente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>CommonSignalPath</code>: Spezialisiert <code>SignalPathConstraint</code>. Enthält per Komposition:\n<ul class=\"fig-list\"><li><code>+signal *</code>: <code>SwcToSwcSignal</code>\n</li><li><code>+operation *</code>: <code>SwcToSwcOperationArguments</code>\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>: Referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+dataElement</code>, Multiplizität 2) das Ziel <code>PortInterface::DataElementPrototype</code>.\n</li><li><code>PortInterface::DataElementPrototype</code>: Stereotyp «atpPrototype», spezialisiert <code>DataPrototype</code>, besitzt das Attribut <code>+isQueued: Boolean</code>.\n</li><li><code>SwcToSwcOperationArguments</code>: Besitzt das Attribut <code>+direction: SwcToSwcOperationArgumentsDirectionEnum</code> und referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+operation</code>, Multiplizität 2) das Ziel <code>PortInterface::OperationPrototype</code>.\n</li><li><code>PortInterface::OperationPrototype</code>: Stereotyp «atpStructureElement», spezialisiert <code>Identifiable</code>.\n</li><li><code>SwcToSwcOperationArgumentsDirectionEnum</code> («enumeration»): Enthält die Literale <code>in</code> und <code>out</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Deklaration von Routing-Bedingungen im Systementwurf. Zur Laufzeit bzw. beim Signal-Routing bindet der Constraint Paare von Modellelementen (Multiplizität 2 bei <code>+dataElement</code> und <code>+operation</code>) an einen gemeinsamen physikalischen Topologiepfad.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell für System-Generatoren und Signal-Router: <code>CommonSignalPath</code> erzwingt, dass zusammengehörige Signale (z. B. Sende- und Empfangsportprototypen eines DataElements) oder Operationsargumente über dieselbe Signalroute in der Fahrzeugtopologie übertragen werden. Die Instanzreferenzen verweisen auf konkrete Prototypen innerhalb der Software-Architektur.</p>"}, {"id": "FIG-b9fb1bc7cbd0e07e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Metamodell-Klassendiagramm für Topologie- und Signalpfad-Constraints im AUTOSAR System Template. Es beschreibt die Struktur von <code>CommonSignalPath</code> zur Erzwingung identischer Übertragungswege für Signale bzw. Operationsargumente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>CommonSignalPath</code>: Spezialisiert <code>SignalPathConstraint</code>. Enthält per Komposition:\n<ul class=\"fig-list\"><li><code>+signal *</code>: <code>SwcToSwcSignal</code>\n</li><li><code>+operation *</code>: <code>SwcToSwcOperationArguments</code>\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>: Referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+dataElement</code>) das Ziel <code>VariableDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code>: Spezialisiert die abstrakte Klasse <code>AutosarDataPrototype</code>.\n</li><li><code>SwcToSwcOperationArguments</code>: Besitzt das Attribut <code>+direction: SwcToSwcOperationArgumentsDirectionEnum</code> und referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+operation</code>) das Ziel <code>ClientServerOperation</code>.\n</li><li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> sowie <code>Identifiable</code>.\n</li><li><code>SwcToSwcOperationArgumentsDirectionEnum</code> («enumeration»): Enthält die Literale <code>in</code> und <code>out</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Definition von gemeinsamen Routingpfaden für Datenprototypen und Client-Server-Operationen in der E/E-Topologie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell: Die Verfeinerung auf <code>VariableDataPrototype</code> und <code>ClientServerOperation</code> bindet die Instanzreferenzen des <code>CommonSignalPath</code> an die standardisierten Daten- und Operationsmetaklassen von AUTOSAR 4.x. Generatoren für Bus- und Gateway-Konfigurationen müssen gewährleisten, dass alle referenzierten Signal- bzw. Operationsendpunkte denselben Signalpfad durch die Netzwerktopologie durchlaufen.</p>"}, {"id": "FIG-a20432e6403653cf", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Metamodell-Klassendiagramm für Topologie- und Signalpfad-Constraints im AUTOSAR System Template. Es beschreibt die Struktur von <code>CommonSignalPath</code> zur Erzwingung identischer Übertragungswege für Signale bzw. Operationsargumente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>CommonSignalPath</code>: Spezialisiert <code>SignalPathConstraint</code>. Enthält per Komposition:\n<ul class=\"fig-list\"><li><code>+signal *</code>: <code>SwcToSwcSignal</code>\n</li><li><code>+operation *</code>: <code>SwcToSwcOperationArguments</code>\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>: Referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+dataElement</code>) das Ziel <code>VariableDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code>: Spezialisiert die abstrakte Klasse <code>AutosarDataPrototype</code>.\n</li><li><code>SwcToSwcOperationArguments</code>: Besitzt das Attribut <code>+direction: SwcToSwcOperationArgumentsDirectionEnum</code> und referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+operation</code>) das Ziel <code>ClientServerOperation</code>.\n</li><li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> sowie <code>Identifiable</code>.\n</li><li><code>SwcToSwcOperationArgumentsDirectionEnum</code> («enumeration»): Enthält die Literale <code>in</code> und <code>out</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Definition von gemeinsamen Routingpfaden für Datenprototypen und Client-Server-Operationen in der E/E-Topologie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell: Die Verfeinerung auf <code>VariableDataPrototype</code> und <code>ClientServerOperation</code> bindet die Instanzreferenzen des <code>CommonSignalPath</code> an die standardisierten Daten- und Operationsmetaklassen von AUTOSAR 4.x. Generatoren für Bus- und Gateway-Konfigurationen müssen gewährleisten, dass alle referenzierten Signal- bzw. Operationsendpunkte denselben Signalpfad durch die Netzwerktopologie durchlaufen.</p>"}, {"id": "FIG-c8557f61b1ad7209", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Metamodell-Klassendiagramm für Topologie- und Signalpfad-Constraints im AUTOSAR System Template. Es beschreibt die Struktur von <code>CommonSignalPath</code> zur Erzwingung identischer Übertragungswege für Signale bzw. Operationsargumente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>CommonSignalPath</code>: Spezialisiert <code>SignalPathConstraint</code>. Enthält per Komposition:\n<ul class=\"fig-list\"><li><code>+signal *</code>: <code>SwcToSwcSignal</code>\n</li><li><code>+operation *</code>: <code>SwcToSwcOperationArguments</code>\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>: Referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+dataElement</code>) das Ziel <code>VariableDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code>: Spezialisiert die abstrakte Klasse <code>AutosarDataPrototype</code>.\n</li><li><code>SwcToSwcOperationArguments</code>: Besitzt das Attribut <code>+direction: SwcToSwcOperationArgumentsDirectionEnum</code> und referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+operation</code>) das Ziel <code>ClientServerOperation</code>.\n</li><li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> sowie <code>Identifiable</code>.\n</li><li><code>SwcToSwcOperationArgumentsDirectionEnum</code> («enumeration»): Enthält die Literale <code>in</code> und <code>out</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Definition von gemeinsamen Routingpfaden für Datenprototypen und Client-Server-Operationen in der E/E-Topologie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell: Die Verfeinerung auf <code>VariableDataPrototype</code> und <code>ClientServerOperation</code> bindet die Instanzreferenzen des <code>CommonSignalPath</code> an die standardisierten Daten- und Operationsmetaklassen von AUTOSAR 4.x. Generatoren für Bus- und Gateway-Konfigurationen müssen gewährleisten, dass alle referenzierten Signal- bzw. Operationsendpunkte denselben Signalpfad durch die Netzwerktopologie durchlaufen.</p>"}, {"id": "FIG-7d9e864e18276561", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Metamodell-Klassendiagramm für Topologie- und Signalpfad-Constraints im AUTOSAR System Template. Es beschreibt die Struktur von <code>CommonSignalPath</code> zur Erzwingung identischer Übertragungswege für Signale bzw. Operationsargumente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>CommonSignalPath</code>: Spezialisiert <code>SignalPathConstraint</code>. Enthält per Komposition:\n<ul class=\"fig-list\"><li><code>+signal *</code>: <code>SwcToSwcSignal</code>\n</li><li><code>+operation *</code>: <code>SwcToSwcOperationArguments</code>\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>: Referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+dataElement</code>, Multiplizität 1) das Ziel <code>VariableDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code>: Spezialisiert die abstrakte Klasse <code>AutosarDataPrototype</code>.\n</li><li><code>SwcToSwcOperationArguments</code>: Besitzt das Attribut <code>+direction: SwcToSwcOperationArgumentsDirectionEnum</code> und referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+operation</code>, Multiplizität 1) das Ziel <code>ClientServerOperation</code>.\n</li><li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> sowie <code>Identifiable</code>.\n</li><li><code>SwcToSwcOperationArgumentsDirectionEnum</code> («enumeration»): Enthält die Literale <code>in</code> und <code>out</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Definition von gemeinsamen Routingpfaden für Datenprototypen und Client-Server-Operationen in der E/E-Topologie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell: Die explizite Kardinalität <code>1</code> an den Instanzreferenzen <code>+dataElement</code> und <code>+operation</code> stellt sicher, dass jede Instanz von <code>SwcToSwcSignal</code> bzw. <code>SwcToSwcOperationArguments</code> genau einen Zielkontext im Modell referenziert. Signal-Routing-Algorithmen und System-Validatoren können sich auf eine eindeutige 1:1-Zuordnung je Instanzreferenz-Element stützen.</p>"}, {"id": "FIG-9c9e08c1813cd16f", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Metamodell-Klassendiagramm für Topologie- und Signalpfad-Constraints im AUTOSAR System Template. Es beschreibt die Struktur von <code>CommonSignalPath</code> zur Erzwingung identischer Übertragungswege für Signale bzw. Operationsargumente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>CommonSignalPath</code>: Spezialisiert <code>SignalPathConstraint</code>. Enthält per Komposition:\n<ul class=\"fig-list\"><li><code>+signal *</code>: <code>SwcToSwcSignal</code>\n</li><li><code>+operation *</code>: <code>SwcToSwcOperationArguments</code>\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>: Referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+dataElement</code>, Multiplizität 1) das Ziel <code>VariableDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code>: Spezialisiert die abstrakte Klasse <code>AutosarDataPrototype</code>.\n</li><li><code>SwcToSwcOperationArguments</code>: Besitzt das Attribut <code>+direction: SwcToSwcOperationArgumentsDirectionEnum</code> und referenziert über eine Instanzreferenz (<code>«instanceRef»</code>, Rolle <code>+operation</code>, Multiplizität 1) das Ziel <code>ClientServerOperation</code>.\n</li><li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> sowie <code>Identifiable</code>.\n</li><li><code>SwcToSwcOperationArgumentsDirectionEnum</code> («enumeration»): Enthält die Literale <code>in</code> und <code>out</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Definition von gemeinsamen Routingpfaden für Datenprototypen und Client-Server-Operationen in der E/E-Topologie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell: Die explizite Kardinalität <code>1</code> an den Instanzreferenzen <code>+dataElement</code> und <code>+operation</code> stellt sicher, dass jede Instanz von <code>SwcToSwcSignal</code> bzw. <code>SwcToSwcOperationArguments</code> genau einen Zielkontext im Modell referenziert. Signal-Routing-Algorithmen und System-Validatoren können sich auf eine eindeutige 1:1-Zuordnung je Instanzreferenz-Element stützen.</p>"}], "trans": [{"from": "FIG-15c200c54b86e1c5", "to": "FIG-aa46f7fbe8833451", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-aa46f7fbe8833451", "to": "FIG-ee1ce48cd516e6d3", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Erweitert um das Metamodell-Klassendiagramm für <code>CommonSignalPath</code> (Spezialisierung von <code>SignalPathConstraint</code>).\n</li><li>Ergänzung der Klassen <code>SwcToSwcSignal</code> (über Komposition <code>+signal *</code>) und <code>SwcToSwcOperationArguments</code> (über Komposition <code>+operation *</code>).\n</li><li><code>SwcToSwcSignal</code> referenziert über eine <code>«instanceRef»</code>-Beziehung <code>+dataElement</code> mit Multiplizität 2 die Klasse <code>PortInterface::DataElementPrototype</code> (<code>«atpPrototype»</code>, spezialisiert <code>DataPrototype</code>, Attribut <code>+isQueued: Boolean</code>).\n</li><li><code>SwcToSwcOperationArguments</code> besitzt das Attribut <code>+direction: SwcToSwcOperationArgumentsDirectionEnum</code> und referenziert über <code>«instanceRef»</code> <code>+operation</code> mit Multiplizität 2 die Klasse <code>PortInterface::OperationPrototype</code> (<code>«atpStructureElement»</code>, spezialisiert <code>Identifiable</code>).\n</li></ul>"}, {"from": "FIG-ee1ce48cd516e6d3", "to": "FIG-b9fb1bc7cbd0e07e", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ziel der <code>«instanceRef»</code>-Assoziation <code>+dataElement</code> von <code>PortInterface::DataElementPrototype</code> auf <code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>) geändert; Multiplizität <code>2</code> entfällt (implizit 1). Attribut <code>isQueued: Boolean</code> entfällt am Datenprototypen.\n</li><li>Ziel der <code>«instanceRef»</code>-Assoziation <code>+operation</code> von <code>PortInterface::OperationPrototype</code> auf <code>ClientServerOperation</code> (spezialisiert <code>AtpStructureElement</code> und <code>Identifiable</code>) geändert; Multiplizität <code>2</code> entfällt (implizit 1).\n</li></ul>"}, {"from": "FIG-b9fb1bc7cbd0e07e", "to": "FIG-a20432e6403653cf", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Trennung der gemeinsamen Textzeile für Rollennamen und Multiplizitäten (<code>+signal *</code> und <code>+operation *</code>) an den Kompositionskanten zur eindeutigen Zuordnung an die jeweiligen Pfeilenden.\n</li></ul>"}, {"from": "FIG-a20432e6403653cf", "to": "FIG-c8557f61b1ad7209", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c8557f61b1ad7209", "to": "FIG-7d9e864e18276561", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Explizite Multiplizitätsangabe <code>1</code> an den Enden der beiden <code>«instanceRef»</code>-Referenzen ergänzt (<code>+dataElement 1</code> und <code>+operation 1</code>).\n</li></ul>"}, {"from": "FIG-7d9e864e18276561", "to": "FIG-9c9e08c1813cd16f", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>SwcToSwcOperationArguments</code>: Leerzeichen im Attribut vor dem Doppelpunkt entfernt (<code>+ direction :SwcToSwcOperationArgumentsDirectionEnum</code> zu <code>+ direction: SwcToSwcOperationArgumentsDirectionEnum</code>).\n</li><li>Leichtes Neu-Rendering des Diagramms ohne inhaltliche Änderungen.\n</li></ul>"}]};
